<script setup lang="ts">import{ref,onMounted}from 'vue';import{reviews,loadReviews}from '../stores/reviews';import{getAudits}from '../api/reviews';import{exportRun}from '../api/runs';import{canEdit}from '../stores/auth';import type{Audit}from '../types/domain';import{useTask}from '../hooks/useTask';import{dateTime}from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import EmptyState from '../components/common/EmptyState.vue';const audits=ref<Audit[]>([]);const{error,execute}=useTask();const refresh=()=>execute(async()=>{await loadReviews();if(canEdit.value)audits.value=await getAudits()});const download=(id:number)=>execute(()=>exportRun(id));onMounted(refresh);</script><template><PageHeading index="06" title="复核与交付登记" subtitle="负责人确认权重的适用范围，阅读者使用同一份归档口径。"/><ErrorNotice :message="error" @retry="refresh"/><EmptyState v-if="!reviews.items.length" title="尚无复核记录" hint="完成一次校准后，由负责人检查诊断并在结果页记录意见。"/><article v-for="r in reviews.items" :key="r.id" class="review-entry"><span class="entry-no">{{String(r.id).padStart(2,'0')}}</span><div><p class="eyebrow">{{dateTime(r.created_at)}} / WT {{r.run_id}}</p><h2>{{r.decision==='approved'?'批准使用的权重口径':'退回的研究口径'}}</h2><p>{{r.note}}</p><RouterLink :to="'/results/'+r.run_id">查阅诊断依据 ↗</RouterLink></div><button v-if="r.decision==='approved'" @click="download(r.run_id)">下载权重 CSV ↓</button></article><template v-if="canEdit"><div class="section-heading"><h2>最近100条操作留痕</h2></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>操作者</th><th>动作</th><th>对象</th></tr></thead><tbody><tr v-for="a in audits" :key="a.id"><td>{{dateTime(a.created_at)}}</td><td>{{a.actor}}</td><td>{{a.action}}</td><td>{{a.target}}</td></tr></tbody></table></div></template></template>
